#!/usr/bin/env bash
# scripts/build-setup-all.sh — joins the 4 migrations + seed.sql + the admin
# promotion into supabase/setup_all.sql, so setup is ONE paste in the SQL Editor.
#   bash scripts/build-setup-all.sh
set -euo pipefail
cd "$(dirname "$0")/.."
{
cat <<'EOF'
-- =====================================================================
-- setup_all.sql — ONE-PASTE SETUP for the Supabase SQL Editor.
-- It is simply the 4 migrations + seed.sql + the admin promotion, in order.
-- (Generated by: bash scripts/build-setup-all.sh — edit the source files, not this one.)
--
-- Before running: create the user studio@artstudio.in in
-- Authentication -> Users -> Add user (tick "Auto Confirm User").
-- Safe to run more than once.
-- =====================================================================
EOF
for f in supabase/migrations/001_schema.sql supabase/migrations/002_auth_and_roles.sql \
         supabase/migrations/003_business_functions.sql supabase/migrations/004_rls_and_grants.sql \
         supabase/seed.sql; do
  echo; echo "-- ##################### $f #####################"; cat "$f"
done
cat <<'EOF'

-- ##################### Studio admin role #####################
-- Gives the seed's studio account the admin role (0 rows if the user
-- hasn't been created yet: create it, then run just this statement again).
update public.profiles
   set role = 'studio', full_name = 'Studio Admin'
 where email = 'studio@artstudio.in';

-- Final check: you should see 12 paintings, 5 items, 6 glazes and 1 studio admin.
select
  (select count(*) from public.paintings)     as paintings,
  (select count(*) from public.pottery_items) as pottery_items,
  (select count(*) from public.glazes)        as glazes,
  (select count(*) from public.profiles where role = 'studio') as studio_admins;
EOF
} > supabase/setup_all.sql
echo "Wrote supabase/setup_all.sql"
